class Report {
  constructor(private title?: string, private footer?: string) {}
}
class ReportBuilder {
  private title?: string;
  private footer?: string;
  setTitle(t: string) { this.title = t; return this; }
  setFooter(f: string) { this.footer = f; return this; }
  build() { return new Report(this.title, this.footer); }
}
const r = new ReportBuilder().setTitle("Q1").setFooter("end").build();

class Config {
  optionA?: string;
  optionB?: number;
  setOptionA(a: string) { this.optionA = a; return this; }
  setOptionB(b: number) { this.optionB = b; return this; }
}
const c = new Config();
c.setOptionA('x');
c.setOptionB(5);
// pass c around and use later

// Version A
class Email {
  constructor(public readonly to: string, public readonly subject?: string) {}
}
class EmailBuilder {
  private to = "";
  private subject?: string;
  setTo(t: string) { this.to = t; return this; }
  setSubject(s: string) { this.subject = s; return this; }
  build() { return new Email(this.to, this.subject); }
}

// Version B
class MutableEmail {
  to = "";
  subject?: string;
  setTo(t: string) { this.to = t; return this; }
  setSubject(s: string) { this.subject = s; return this; }
}
const e = new MutableEmail();
e.setTo("a@b.com");
e.setSubject("hi");
